function KARP_MIN_CYCLE_MEAN(A):
  # Compute shortest k-step walks for k = 0..n
  dist[0, :] = 0
  for k = 1 to n:
    for i = 1 to n:
      dist[k, i] = min over j of (A[i,j] + dist[k-1, j])
  # Apply Karp's formula
  lambda* = min over i of max over k<n of (dist[n,i] - dist[k,i]) / (n-k)
  return lambda*

